import{_ as c,C as r,o as n,c as d,a5 as l,E as t,j as e,a as i,b as A,w as o,a6 as u}from"./chunks/framework.D_J2JZBr.js";const T=JSON.parse('{"title":"射频、微波与电磁","description":"从天线、微波电路到超构表面与电磁成像，认识上科大的高频研究入口。","frontmatter":{"title":"射频、微波与电磁","description":"从天线、微波电路到超构表面与电磁成像，认识上科大的高频研究入口。"},"headers":[],"relativePath":"explore-ic/research-directions/rf-em.md","filePath":"explore-ic/research-directions/rf-em.md","lastUpdated":1795531638000}'),B={name:"explore-ic/research-directions/rf-em.md"};function f(p,a,m,g,b,_){const E=r("FacultyList"),s=r("CourseTable"),h=r("Mermaid");return n(),d("div",null,[a[1]||(a[1]=l('<h1 id="射频、微波与电磁" tabindex="-1">射频、微波与电磁 <a class="header-anchor" href="#射频、微波与电磁" aria-label="Permalink to &quot;射频、微波与电磁&quot;">​</a></h1><h2 id="这个方向在做什么" tabindex="-1">这个方向在做什么 <a class="header-anchor" href="#这个方向在做什么" aria-label="Permalink to &quot;这个方向在做什么&quot;">​</a></h2><p>射频（Radio Frequency，RF）与微波研究高频信号的产生、传输、辐射、接收和相互作用。当结构尺寸与波长可比时，连线不再只是理想导线，分布参数、传播相位和空间场分布都必须纳入设计。因此，这个方向既有晶体管与电路，也有天线、传输线、材料和电磁场计算。</p><p>核心研究问题包括：</p><ul><li>怎样在增益、噪声、线性度、带宽与效率之间权衡射频前端？</li><li>天线的辐射、匹配、极化与阵列耦合如何共同影响系统？</li><li>微波、毫米波和太赫兹器件受哪些材料及工艺约束？</li><li>超构表面如何调控电磁波，实际损耗和带宽限制是什么？</li><li>如何从测得的场或散射信息恢复目标结构，实现成像与感知？</li><li>AI 辅助电磁设计怎样满足物理约束并接受独立验证？</li></ul><h2 id="上科大谁在做" tabindex="-1">上科大谁在做 <a class="header-anchor" href="#上科大谁在做" aria-label="Permalink to &quot;上科大谁在做&quot;">​</a></h2><p>上科大相关公开研究覆盖场、器件与系统。林丰涵的超感知实验室关注模式与结构电磁学、天线理论与技术、微波电路与器件、电磁波调控及 AI 辅助电磁设计。王雄的方向包括微波/毫米波/超声生物医学成像、电磁波与声波调控、超构表面和物理神经网络，这条路线强调场作用与成像问题。</p><p>器件侧，邹新波关注 GaN 基微波与毫米波器件及宽禁带陷阱物性，曹文翰的方向包含太赫兹超表面器件。廖立杨研究面向量子信息、射频器件与电源管理的自旋电子学混合系统；傅旻帆的公开方向还包括射频功放、无线传能和电磁兼容。这些关联不表示所有课题都属于射频集成电路设计，应根据具体论文判断研究对象。</p>',8)),t(E,{dir:"rf"}),a[2]||(a[2]=e("h2",{id:"相关上科大课程",tabindex:"-1"},[i("相关上科大课程 "),e("a",{class:"header-anchor",href:"#相关上科大课程","aria-label":'Permalink to "相关上科大课程"'},"​")],-1)),a[3]||(a[3]=e("p",null,"从电磁学建立场与波的语言，再进入微波工程和天线课程；电路与器件课程有助于理解有源前端。",-1)),t(s,{codes:"EE130,EE130P,EE230,EE234B,EE111,EE115A,EE120"}),a[4]||(a[4]=e("h2",{id:"知识前置",tabindex:"-1"},[i("知识前置 "),e("a",{class:"header-anchor",href:"#知识前置","aria-label":'Permalink to "知识前置"'},"​")],-1)),a[5]||(a[5]=e("p",null,"下图给出建议学习路线，不代表正式先修关系；复数、向量分析、微分方程与数值计算应同步补齐。",-1)),(n(),A(u,null,{default:o(()=>[t(h,{id:"mermaid-69",class:"mermaid",graph:"graph%20TD%0A%20%20A%5B%22%E6%95%B0%E5%AD%A6%E4%B8%8E%E6%99%AE%E9%80%9A%E7%89%A9%E7%90%86%22%5D%20--%3E%20B%5B%22EE130%20%E7%94%B5%E7%A3%81%E5%AD%A6%22%5D%0A%20%20B%20--%3E%20C%5B%22EE130P%20%E7%94%B5%E7%A3%81%E5%AD%A6%E8%AF%BE%E7%A8%8B%E8%AE%BE%E8%AE%A1%22%5D%0A%20%20B%20--%3E%20D%5B%22EE230%20%E5%BE%AE%E6%B3%A2%E5%B7%A5%E7%A8%8BI%22%5D%0A%20%20B%20--%3E%20E%5B%22EE234B%20%E5%A4%A9%E7%BA%BF%E7%90%86%E8%AE%BA%E4%B8%8E%E8%AE%BE%E8%AE%A1%22%5D%0A%20%20F%5B%22EE111%20%E7%94%B5%E8%B7%AF%E5%9F%BA%E7%A1%80%22%5D%20--%3E%20G%5B%22EE115A%20%E6%A8%A1%E6%8B%9F%E7%94%B5%E8%B7%AF%22%5D%0A%20%20H%5B%22EE120%20%E5%8D%8A%E5%AF%BC%E4%BD%93%E5%99%A8%E4%BB%B6%E5%9F%BA%E7%A1%80%22%5D%20--%3E%20I%5B%22%E9%AB%98%E9%A2%91%E5%99%A8%E4%BB%B6%E4%B8%8E%E7%94%B5%E8%B7%AF%22%5D%0A%20%20G%20--%3E%20I%0A%20%20D%20--%3E%20I%0A%20%20C%20--%3E%20J%5B%22%E5%B0%84%E9%A2%91%E3%80%81%E5%BE%AE%E6%B3%A2%E4%B8%8E%E7%94%B5%E7%A3%81%E7%A0%94%E7%A9%B6%22%5D%0A%20%20E%20--%3E%20J%0A%20%20I%20--%3E%20J%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<h2 id="领域地图" tabindex="-1">领域地图 <a class="header-anchor" href="#领域地图" aria-label="Permalink to &quot;领域地图&quot;">​</a></h2><ul><li><strong>研究机构</strong>：MIT、UCLA、清华、东南大学与电子科技大学的相关团队，可作为高频电路、天线和电磁研究的检索起点。要区分器件物理、场求解与通信系统等不同问题。</li><li><strong>产业参照</strong>：Qualcomm、Broadcom、Qorvo 的射频产品，以及 Keysight、Rohde &amp; Schwarz 的测试体系，有助于认识系统规格与测量条件；并非本校合作名单。</li><li><strong>会议与期刊</strong>：IMS、RFIC，以及 IEEE Transactions on Microwave Theory and Techniques（TMTT）；天线与传播方向关注 IEEE AP-S/URSI 和 IEEE Transactions on Antennas and Propagation（TAP）。集成射频电路也常见于 ISSCC、JSSC。</li></ul><p>比较指标时要注明频段、带宽、参考阻抗与测量参考面。芯片、探针、封装、连接线和天线的损耗不能随意混算；仿真结果也不能自动当作实测结果。</p><h2 id="入门资源" tabindex="-1">入门资源 <a class="header-anchor" href="#入门资源" aria-label="Permalink to &quot;入门资源&quot;">​</a></h2><ul><li><a href="/shanghaitech-ic-wiki-dev.github.io/learning/analog-ic/resources">模拟自学</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/learning/devices-and-process/resources">器件自学</a>：分别补有源电路与器件知识。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/learning/fundamentals/">基础自学</a>：补电磁场所需数学与信号分析。</li><li><a href="https://mtt.org/" target="_blank" rel="noreferrer">IEEE Microwave Theory and Technology Society</a>：微波领域会议、期刊与教育资源。</li><li><a href="https://www.ieeeaps.org/" target="_blank" rel="noreferrer">IEEE Antennas and Propagation Society</a>：天线与传播方向入口。</li></ul><p>可先学习传输线与阻抗匹配，用一个简单结构连接等效电路、全波模型与测量量。射频发射、强场和高功率实验须遵守频谱管理及实验室安全要求。</p><h2 id="社区经验征集" tabindex="-1">社区经验征集 <a class="header-anchor" href="#社区经验征集" aria-label="Permalink to &quot;社区经验征集&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">征集</p><p>欢迎该方向课题组同学通过 <a href="/shanghaitech-ic-wiki-dev.github.io/community/contributing">参与共建</a> 补充“组里在做什么”、公开仿真与仪器学习路径、进组准备建议；不披露未公开参数、设备账号或受限资料。</p></div><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://sist.shanghaitech.edu.cn/linfh/main.htm" target="_blank" rel="noreferrer">林丰涵学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/wangxiong/main.htm" target="_blank" rel="noreferrer">王雄学院主页</a>。</li><li><a href="https://sist.shanghaitech.edu.cn/zouxb/main.htm" target="_blank" rel="noreferrer">邹新波学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/cwh/main.htm" target="_blank" rel="noreferrer">曹文翰学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/lly1/main.htm" target="_blank" rel="noreferrer">廖立杨学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/fumf/main.htm" target="_blank" rel="noreferrer">傅旻帆学院主页</a>。</li><li><a href="https://sist.shanghaitech.edu.cn/_upload/article/files/d0/82/218152ad4bd29c54d8a89d0e6be7/2cba84cd-d335-4a72-8f17-68175bed8e69.pdf" target="_blank" rel="noreferrer">后摩尔中心介绍材料</a>：约 2024 年方向介绍。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">2026–2027 学年 SIST 开课计划</a>：课程安排以教务系统为准。</li></ul>',10))])}const I=c(B,[["render",f]]);export{T as __pageData,I as default};
